        "kind": "number",
        "text": "5. 对批评微笑。试着理解：分歧与不和为何表明人与人之间的差异，并把这一点当作让你的价值判断服务于成长的机会——因为它们正是如此。不要为别人的批评感到自责，而要试着倾听它，理解它在自己内心引发的感受与意象。然后你或许会看到一条道路，不仅通向一致，更通向一个共同的、真正有价值的结果。"
