        "text": "上述大多数问题都可以看作外倾思维功能过度主导、统治人格的直接结果。在大多数情况下，这正是正在发生的事；但也值得认识到，ENTJ 人格中那些在其他类型看来更明显的弱点，与其说源于 ENTJ 主导功能的过度，不如说源于其情感功能的天然劣势及其缺乏适应。我们还必须认识到，所有人身上所有功能的表达水平都是可变的，这里讨论的一些问题只适用于强烈表达的 ENTJ——此时，纯粹使用外倾思维来引导人生的态度，会产生其自身特有的问题。"
