        "text": "5. 你一生气，你就输了。你的精力与理性理解是强大的资产，但如果它们反噬于你，让你只剩下无法处理的情绪，它们就可能非常有害。记住，不能总指望他人落入你的看问题方式；当你驱使他们这样做而失败时，你会遭受怨恨甚至被抛弃的感觉。你不能这样与世界打交道。调和你的想法，允许他人有自己的空间，你就会成长。"
