      {
        "kind": "heading",
        "text": "成功的意义（What Does Success Mean）"
      },
      {
        "kind": "paragraph",
        "text": "ENFP 所做的一切事情，都由一种理解周围世界的渴望所驱动。他们不断搜索——在精神上和身体上——寻找能帮助他们更好地理解“大局”的输入。他们对新人和新体验持开放态度；他们渴望有机会弄清新人和新体验到底是怎么一回事。ENFP 用自己对世界的理解来服务其价值体系的议程。ENFP 的价值体系通常包括：尊重个体人的需要与愿望，胜过尊重社会群体的需要。他们对个体的尊重使他们不喜欢控制他人、也不喜欢被他人控制。ENFP 对自己的信念充满热情，无论这些信念是什么。他们常常顽固地坚守自己的价值体系，不管它的有效性受到何种威胁。他们更关心忠于自己所信，而不是关心他们身处其中的社会群体的期望或要求。ENFP 不喜欢针对个人的批评，因为它威胁到自己作为个体的有效性及其价值体系的有效性。ENFP 可能把愤怒内化而不是表达出来；他们对其他个体的尊重使他们难以伤害他人。ENFP 的成就感取决于：是否有机会增长自己对世界的理解、是否感觉自己忠于自己的个人价值体系、以及他们最亲密关系的状况。"
      },
      {
        "kind": "heading",
        "text": "让优势绽放（Allowing Your Strengths to Flourish）"
      },
      {
        "kind": "paragraph",
        "text": "作为 ENFP，你拥有专属于这一人格类型、并非其他类型天生优势的天赋。通过认识到这些特别的天赋并鼓励其成长发展，你将更容易看到自己在世界中的位置，对自己的角色更加满意。"
      },
      {
        "kind": "paragraph",
        "text": "几乎所有 ENFP 都能在自己身上认出以下特质。他们应当拥抱并滋养这些优势："
      },
      {
        "kind": "bullet",
        "text": "• 他们对人和情境有着非凡的洞察力。他们常常能迅速而准确地判断出对方“从何而来”。"
      },
      {
        "kind": "bullet",
        "text": "• 他们把人作为个体来接受和珍视，并强烈信奉平等主义。他们相信个体有权做自己，对大多数人非常宽容和接纳。"
      },
      {
        "kind": "bullet",
        "text": "• 他们通常深刻而聪明，在把事物联系起来的能力上可能相当出色。他们的思维构造就是寻找外部世界中的联系，因此他们可能在头脑中比其他人更容易把事物拼合起来。"
      },
      {
        "kind": "bullet",
        "text": "• 他们对理解世界的兴趣，通常使他们敏锐地感知什么为社会所接受、什么不是。这可能帮助他们受欢迎、讨人喜欢。"
      },
      {
        "kind": "bullet",
        "text": "• 他们极具创造力。这种能力可能以艺术的方式使用，也可能用于产生想法和新的思维方式。"
      },
      {
        "kind": "paragraph",
        "text": "ENFP 若将内倾情感（Introverted Feeling）发展到能对所有感知运用判断的程度，将享有这些非常特别的礼物："
      },
      {
        "kind": "bullet",
        "text": "• 他们将有能力把已开始的项目做完。"
      },
      {
        "kind": "bullet",
        "text": "• 他们将不那么轻信、不那么容易受影响，总体上更能分辨“好”与“坏”，而不是不加质疑地接受一切。"
      },
      {
        "kind": "bullet",
        "text": "• 他们可能极具艺术天赋。"
      },
      {
        "kind": "bullet",
        "text": "• 他们将有能力深度专注和集中精力于任务。这种增强的内在思考与信息处理能力将使他们在许多层面上更有能力。"
      },
      {
        "kind": "bullet",
        "text": "• 他们将把自己结识新人、体验新事物的愿望，与以某种方式运用自己理解的愿望平衡起来。"
      },
      {
        "kind": "bullet",
        "text": "• 他们将为自己的生活找到更多的意义与目的。"
      },
      {
        "kind": "heading",
        "text": "潜在问题领域（Potential Problem Areas）"
      },
      {
        "kind": "paragraph",
        "text": "任何天赋都伴随着相应的弱点。没有“坏”，就没有“好”。没有“难”，就没有“易”。我们珍视自己的长处，却常常诅咒并忽视自己的弱点。要成长为人、从生活中得到想要的东西，我们不仅要善用自己的长处，还要直面弱点并加以处理。这意味着要认真审视自己人格类型的潜在问题领域。"
      },
      {
        "kind": "paragraph",
        "text": "ENFP 大多数较弱的特质，源于其主导功能——外倾直觉（Extraverted Intuition）——遮蔽了人格，以至于他们不对任何事情运用判断。或者，他们可能用其主要的判断功能（内倾情感）来支持外倾直觉的议程，即：为“欢迎一切体验、接纳一切个体”的想法提供合理化和支持。在这种情况下，ENFP 可能在不同程度上表现出以下部分或全部弱点："
      },
      {
        "kind": "bullet",
        "text": "• 可能是许多人所说的“冤大头”；容易受到阴谋家和骗子的伤害。"
      },
      {
        "kind": "bullet",
        "text": "• 可能把自己卷入危险的处境，因为他们过于急切地要突破自己理解的边界，而不愿意对任何事情运用判断。"
      },
      {
        "kind": "bullet",
        "text": "• 可能对批评自己或试图控制自己的人感到强烈愤怒，但无法表达这种愤怒。若得不到表达，愤怒可能溃烂、闷烧，变得具有破坏性。"
      },
      {
        "kind": "bullet",
        "text": "• 可能把自己的问题归咎于他人，用逻辑和理性为自己辩护，对抗世界。"
      },
      {
        "kind": "bullet",
        "text": "• 可能对自认为压迫过自己的人产生难以消除的强烈负面判断。"
      },
      {
        "kind": "bullet",
        "text": "• 可能沾染毒品、酒精或滥交，总体上寻求无意识、无意义的体验与感官刺激。"
      },
      {
        "kind": "bullet",
        "text": "• 可能在一段又一段关系之间跳来跳去，而没有能力作出承诺。"
      },
      {
        "kind": "bullet",
        "text": "• 可能开始一些项目，却无法完成。"
      },
      {
        "kind": "bullet",
        "text": "• 可能无法在任何一段时期内坚持一份职业或工作。"
      },
      {
        "kind": "heading",
        "text": "问题解析（Explanation of Problems）"
      },
      {
        "kind": "paragraph",
        "text": "上述几乎所有问题特质都可不同程度地归因于 ENFP 常见的问题：不惜一切代价地想要理解和体验一切。如果 ENFP 学不会辨别外部环境中的人与事物，ENFP 将开始用其判断功能（内倾情感）作为“橡皮图章”，支持其寻求体验的议程。这是 ENFP 人格自然的生存技巧。ENFP 人格的主要驱动力是外倾直觉，其目的是把世界理解为一个整体“大图景”，在一切事物中寻找联系与意义。如果他们寻求理解的能力受到威胁，ENFP 会把威胁力量挡在外面。这完全自然，但不幸的是，经常实施这种“议程保护”的个体，将越来越无法对任何事情运用判断。失衡的 ENFP 即便运用判断，通常也会被扭曲以支持其主观议程。他们总会为自己的不当行为找到理由。他们将无法完成任何开始的事情，总体上在人生中从一个体验飘荡到另一个体验。"
      },
      {
        "kind": "paragraph",
        "text": "ENFP 抗拒运用判断，直到他们觉得自己真正理解了一个人或一种情境，这是非常常见的。然而，理解过程的一部分就包括运用辨别力来对特质进行分类。如果 ENFP 完全关掉判断，他或她将无法达到理解的终极目标；相反，他们将漫无目的地从一个体验跳到另一个体验。"
      },
      {
        "kind": "paragraph",
        "text": "愤怒可能对任何人都是问题，但对那些未充分发展内倾情感的 ENFP 来说尤其如此。保持一切不加评判的愿望，加上把内倾情感用作合理化工具而非真正判断的倾向，是压抑愤怒的配方。这些是非常矛盾的力量。“我恨你评判我”是一种讽刺性的感受，但不幸的是它很常见。无法运用判断或接受负面判断，使 ENFP 无法表达负面判断，因此导致他们沉浸在愤怒中，而不是处理它。"
      },
      {
        "kind": "heading",
        "text": "解决方案（Solutions）"
      },
      {
        "kind": "paragraph",
        "text": "要作为个体成长，ENFP 需要专注于对所有感知运用判断。这意味着他们需要决定自己对人物、地点和事物究竟有何感受，而不是让感受悬而未决。ENFP 需要明白：培养辨别特质的能力并不会威胁他们理解世界的能力，反而会增强它，也会增加他们在生活中取得一定成功的机会。"
      },
      {
        "kind": "paragraph",
        "text": "关心个人成长的 ENFP，会密切关注自己作出判断时的动机。他们是在努力真正确定某事物的客观价值或优点，还是在努力捍卫自己“不被评判、不被控制”的个人权利？判断某事物时的目标，是不要让自己的个人议程影响自己的意见。显然，这不可能完全做到，但这是要铭记在心的练习。你要在不受威胁、且不以防御性、合理化的方式运用自己判断的前提下，向判断敞开自己的心灵。"
      },
      {
        "kind": "heading",
        "text": "在世界中幸福生活（Living Happily）"
      },
      {
        "kind": "paragraph",
        "text": "由上可见，一些 ENFP 可能难以融入社会。他们的问题常常源于：由于主导的直觉而感到自己与他人不同，以及无法把任何事坚持到足以产生成就感的地步。他们感觉自己格格不入，无法在世界中找到属于自己的位置。持续作出决定并对自己的想法运用分类的 ENFP，将能把想法变成现实，并体验伴随高效而来的成就感与成功感。"
      },
      {
        "kind": "paragraph",
        "text": "ENFP 个人成长的关键，是熟练地运用内倾情感（Introverted Feeling）。大多数人很难理解这意味着什么，更不用说把这一指引融入生活。我设计了一些以行动为导向的建议，帮助你走上更有效运用内倾情感功能的道路。具体建议："
      },
      {
        "kind": "heading",
        "text": "具体建议（Specific Suggestions）："
      },
      {
        "kind": "paragraph",
        "text": "当你对某个你觉得在批评你的人感到愤怒或抗拒时，把这当作一个信号：你没有在有效地进行判断。当这种情况发生时，从愤怒中退后一步，试着客观地真正倾听那个人在说什么。不要把精神能量花在界定对方错在哪里上，而要试着判断那个人实际上在说什么。"
      },
      {
        "kind": "paragraph",
        "text": "定期列出目标与成就的清单。随心所欲地时常重访自己的目标与成就，以保持方向感。"
      },
      {
        "kind": "paragraph",
        "text": "定期独处，用于思考生活中的问题。"
      },
      {
        "kind": "heading",
        "text": "十条生活准则（Ten Rules to Live By）"
      },
      {
        "kind": "number",
        "text": "1. 滋养你的优势！确保你有机会获得新体验，去感受你对理解世界的追求。"
      },
      {
        "kind": "number",
        "text": "2. 直面你的弱点！认识并接受：有些特质是长处，有些是弱点。直面弱点，你就能克服它们，它们对你的控制力也会减弱。"
      },
      {
        "kind": "number",
        "text": "3. 表达你的感受。不要让愤怒积压在内心。如果你有强烈的感受，把它们理清并表达出来，否则它们可能变得具有破坏性！"
      },
      {
        "kind": "number",
        "text": "4. 作出决定。不要害怕有自己的见解。为了保有成效，你需要知道自己对事物有何感受。"
      },
      {
        "kind": "number",
        "text": "5. 对批评微笑。试着把分歧与不和视为成长的机会——因为它们正是如此。不要对批评过度防御；试着倾听它并客观地判断它。"
      },
      {
        "kind": "number",
        "text": "6. 觉察他人。记住，世界上还有 15 种以与你不同的方式看待事物的人格类型。如果你试着理解对方的视角，你与大多数人的问题都会更容易处理。"
      },
      {
        "kind": "number",
        "text": "7. 觉察自己。不要为了他人而过分克扣自己的需要。认识到你是重要的焦点。如果你不满足自己的需要，你如何继续保有成效？他人又如何知道你忠于自己的信念？"
      },
      {
        "kind": "number",
        "text": "8. 对自己负责。不要浪费精神能量去他人的行为中找错，或把自己认定为受害者。你对生活的控制超过其他任何人。"
      },
      {
        "kind": "number",
        "text": "9. 假定最好的可能。不要因假定最坏而让自己痛苦。记住，积极的态度创造积极的境况。"
      },
      {
        "kind": "number",
        "text": "10. 心存疑虑时，提出问题！不要以为缺少反馈就等于负面反馈。如果你需要反馈而没有任何反馈，就去要。"
      }
