        "kind": "number",
        "text": "1. 滋养你的优势！给自己一切机会展示你的天赋技能。如果你现在的关系或工作不允许这样，也许是时候找出改变的办法。记住，你的优势源于能够与世界打交道、与那些存在把事情做完和克服困难机会的情境打交道。"
