        "kind": "number",
        "text": "9. 意识到你可能失败，而那没关系。不是每座山都能攀登，不是每个客户都能满意，无论你多努力或使用什么技巧。被打败是反思什么重要、什么在生命中真正要紧的机会。下一次你将接受一个更配得上你技能、对他人更有价值的挑战。你可以成为冠军，而且将是在你自己的比赛中。试着让它成为一场生活的游戏，在其中你赢则人人皆赢。"
