        "text": "INFJ 是温暖而善于肯定的、通常也深沉复杂的人。他们很可能寻求并促进强烈而有意义的关系。他们倾向于成为完美主义者，总是为终极关系而奋斗。在大多数情况下，这是一个积极的特质，但如果 INFJ 养成一段又一段关系地转换、总在寻找更完美伴侣的习惯，有时也会对他们不利。总体而言，INFJ 是深沉温暖、关爱他人的人，高度投入于亲密关系的健康，投入大量努力使其变得积极。他们因这些特殊品质而受亲近之人珍视。他们寻求长期、终身的关系，虽然他们并不总能找到。"
