        "text": "上述几乎所有问题特质都可不同程度地归因于 INFP 常见的问题：只接收证明其个人意见合理的数据。INFP 通常是非常强烈而敏感的人，感到被批评严重威胁。他们很可能把任何不同于自己的观点都视为对自己视角的批评。如果 INFP 学不会处理这种被感知的批评，INFP 将开始挡掉那些带来痛苦的信息。这是 INFP 人格自然的生存技巧。INFP 人格的主要驱动力是内倾情感，其目的是维持并尊崇一套强烈个人化的价值与道德体系。如果 INFP 的个人价值体系受到外部影响的威胁，INFP 会挡掉威胁性数据，以保存并尊崇自己的价值体系。这完全自然，而且能有效保护个体心灵免受伤害。然而，经常实施这种自我保护的 INFP，将越来越意识不到他人的视角，从而越来越脱离对自己所生活世界的真实理解。他们总会为自己的不当行为找到理由，也总会为生活中的问题在外部世界找茬。他们将难以维持亲密的个人关系，因为他们会有不合理的期望，并且无法接受指责。"
