        "text": "以内倾直觉主导其人格，INTJ 把能量集中于观察世界、产生想法与可能性。他们的头脑不断收集信息并作出联想。他们极其有洞察力，通常能非常快速地理解新想法。然而，他们的主要兴趣不是理解一个概念，而是以有用的方式应用那个概念。与 INTP 不同，他们不会尽最大可能地追随一个想法，仅仅寻求彻底理解它。INTJ 被驱使着对想法得出结论。他们对了结与组织的需要，通常要求他们采取某种行动。"
