        "text": "INTJ 对体系与组织的巨大价值和需要，加上其天然的洞察力，使他们成为出色的科学家。一位 INTJ 科学家通过把想法以对他人的有用形式呈现出来，向社会贡献一份礼物。表达内在意象、洞察和抽象对 INTJ 来说并不容易。INTJ 思想与概念的内在形式高度个人化，不容易转化为他人能理解的形式。然而，INTJ 被驱使着把自己的想法转化为通常易于解释的计划或体系，而不是直接转译自己的思想。他们通常看不到直接转译的价值，也会难以表达自己非线性的想法。然而，他们对知识与智力的极度尊重会激励他们向自己觉得值得费力的人解释自己。"
