        "kind": "paragraph",
        "text": "INTJ 中发现的多数较弱特质，源于其主导功能（内倾直觉——Introverted iNtuition）接管了人格，以至于人格中的其他力量仅仅为内倾直觉的目的而存在。在这种情况下，INTJ 可能在不同程度上表现出以下部分或全部弱点："
