        "text": "上述几乎所有问题特质都可不同程度地归因于 INTP 常见的问题：只接收与自身生活经验相关或支持自身生活经验的信息。INTP 被驱使着通过把逻辑（一种即时的、空间的、“模糊”的逻辑）应用于当前情境来工作和理解他或她的世界。虽然他们通常寻求揭示真理，但他们并不总是在逻辑过程中心中有一个要实现的目标。运用逻辑的行为或过程对 INTP 来说本身就是奖励。在他们对“掌握一个问题或情境带来的满足感”的热忱中，INTP 常常选择性地把自己置于有机会锻炼这些技能的情境中。这当然不是问题。大多数人格类型最常选择做自己最擅长的事。这就是善用我们长处之本。当 INTP 的目标变成不惜一切代价实现个人满足时，问题就露出了狰狞面目。"
