        "kind": "bullet",
        "text": "• 他们把人作为个体来接受和珍视，并强烈信奉平等主义。他们相信个体有权做自己，而不让自己的态度和视角受到审视。因此，他们处理那些可能受到社会普遍负面评判的人时有大量宽容和接纳。他们能在每个人身上看到积极的东西。他们相信个体。如果给自己机会，ISFP 可以成为那些无法自己找到自尊与自信之人亟需的自尊与自信源泉。如此，他们能把一个“病态的灵魂”滋养回健康。"
