      {
        "kind": "heading",
        "text": "问题解析（Explanation of Problems）"
      },
      {
        "kind": "paragraph",
        "text": "上述几乎所有问题特质都可不同程度地归因于 ISFP 常见的问题：只接收证明其个人意见合理的数据。ISFP 通常是非常强烈而敏感的人，感到被批评严重威胁。他们很可能把任何不同于自己的观点都视为对自己视角的批评。如果 ISFP 学不会处理这种被感知的批评，ISFP 将开始挡掉那些带来痛苦的信息。这是 ISFP 人格自然的生存技巧。ISFP 人格的主要驱动力是内倾情感，其目的是维持并尊崇一套强烈个人化的价值与道德体系。如果 ISFP 的个人价值体系受到外部影响的威胁，ISFP 会挡掉威胁性数据，以保存并尊崇自己的价值体系。这完全自然，而且能有效保护个体心灵免受伤害。然而，经常实施这种自我保护的 ISFP，将越来越意识不到他人的视角，从而越来越脱离对自己所生活世界的真实理解。他们总会为自己的不当行为找到理由，也总会为生活中的问题在外部世界找茬。他们将难以维持亲密的个人关系，因为他们会有不合理的期望，并且无法接受指责。"
      },
      {
        "kind": "paragraph",
        "text": "ISFP 主要向外部世界寻求支持其想法与价值的信息，这并非罕见倾向。然而，若这一倾向放任自流，形成的 ISFP 人格将过于自我中心，难以幸福或成功。由于 ISFP 人格的主导功能是内倾情感，他们必须用辅助的外倾感觉功能来平衡它。ISFP 通过外倾感觉获取信息。这也是 ISFP 处理外部世界的主要方式。如果 ISFP 只把外倾感觉用于服务内倾情感的目的，那么 ISFP 完全没有有效地运用外倾性。结果，ISFP 没有获取足够多关于外部世界的信息来对正在发生之事有良好的感知。他们只见自己的视角，只在与支持自己视角所需的最低限度上与世界打交道。这些个体通常显得自私而不切实际。视问题的严重程度，他们可能显得从“有点古怪”到“不着边际”的任何样子。很多时候，其他人无法理解或认同这些人。"
      },
      {
        "kind": "heading",
        "text": "解决方案（Solutions）"
      },
      {
        "kind": "paragraph",
        "text": "要作为个体成长，ISFP 需要专注于开阔自己的视角，纳入对世界上真正发生之事更准确的图景。为了能够感知并考虑与其内在价值体系相异的数据，ISFP 需要知道：自己的价值体系并不会被新信息威胁。ISFP 必须有意识地告诉自己：一种与其自身不一致的意见，并不是对其整个性格的控诉。"
      },
      {
        "kind": "paragraph",
        "text": "关心个人成长的 ISFP，会密切关注自己获取信息的动机。他们获取信息是为了更好地理解一种情境或概念吗？还是为了支持一种个人想法或事业？当感知到某事物时，ISFP 是关心扭曲那种感知以符合个人价值吗？还是他/她关心客观地吸收信息？为了更好地理解外部世界，ISFP 应尝试在把信息纳入价值体系之前先客观地感知它。他们应有意识地觉察自己“丢弃一切与其价值不符之物”的倾向，并努力减弱这一倾向。他们应尝试从他人的视角看待情境，而不对情境或他人视角作个人判断。总之，他们应努力以真正外倾的意义来运用自己的感觉。换句话说，他们应运用感觉获取周围世界的信息，以理解世界为目的，而不是获取信息来支持自己的结论。能够客观感知事物的 ISFP，可以成为推动积极改变的强大力量。"
      },
      {
        "kind": "heading",
        "text": "在世界中幸福生活（Living Happily）"
      },
      {
        "kind": "paragraph",
        "text": "有些 ISFP 难以融入我们的社会。他们的问题往往是以下原因的结果：意识不到恰当的社会行为、意识不到自己在他人眼中的形象，或对他人有不切实际的期望。这三个问题中的任何一个都源于以减弱的方式运用外倾感觉（Extraverted Sensing）。一个为了理解周围世界而获取信息、而非只获取信息来支持自己想法的 ISFP，将对社会如何评价社会行为与态度有更清晰、更客观的理解。他或她也会更觉察自己如何被他人看待，并对关系中他人的行为有更现实的期望。这样适应良好的 ISFP 将幸福地融入我们的社会。"
      },
      {
        "kind": "paragraph",
        "text": "除非你真正理解心理类型理论及各人格功能的细微差别，否则突然开始以外倾方向运用感觉是很困难的任务。甚至难以理解那意味着什么，更不用说把这一指引融入生活。考虑到这一点，我提供一些具体建议，可能帮助你开始更充分地练习你的外倾感觉："
      },
      {
        "kind": "heading",
        "text": "具体建议（Specific Suggestions）："
      },
      {
        "kind": "paragraph",
        "text": "留意观察人们在不同社会情境中的样子。看看他们的头发、皮肤、妆容（或没有妆容）、衣服、衣服的状况、鞋子、面部表情。不要把他人的外表与自己的相比较，也不要评判他们的外表，只须接收这些信息。"
      },
      {
        "kind": "paragraph",
        "text": "想想你生活中一个不确定该如何行事的情境。现在试着理解一两个人会如何看待当时的情境。不要把自己的行为与他们的相比较，比如“她会比我更知道该怎么做”，或“为什么对她这么容易，对我这么难”。相反，试着理解他们会如何看待当时的情境。它会被视为一个问题，还是一个机会？它会被严肃对待还是轻描淡写？试着确定他们的观点，而不作评判、也不与自己的观点比较。"
      },
      {
        "kind": "paragraph",
        "text": "与朋友或亲戚交谈时，至少把一半时间用于谈论对方。专注于真正理解对方带着关切“从何而来”。提出问题。"
      },
      {
        "kind": "paragraph",
        "text": "想一想与你最亲近的人。每想到一个人，就告诉自己：“这个人有自己的生活在进行，他们更关心自己的生活，而不是我的。”记住，这并不意味着他们不关心你。这是事物的自然秩序。试着想象那个人此刻正在做什么。他们正遇到什么事，他们正怀着什么想法？不要作评判，也不要把他们的处境与你的相比较。"
      },
      {
        "kind": "paragraph",
        "text": "试着为你接触到的每一个相处过一段时间的人判断其人格类型。"
      },
      {
        "kind": "heading",
        "text": "十条生活准则（Ten Rules to Live By）"
      },
      {
        "kind": "number",
        "text": "1. 滋养你的优势！鼓励你天然的艺术能力与创造力。滋养你的灵性。给自己帮助有需要者或弱势者的机会。"
      },
      {
        "kind": "number",
        "text": "2. 直面你的弱点！认识并接受：有些特质是长处，有些是弱点。直面并处理你的弱点，并不意味着你必须改变自己；它意味着你想成为尽可能好的自己。直面弱点，就是在尊重真实的自己，而不是攻击自己。"
      },
      {
        "kind": "number",
        "text": "3. 表达你的感受。不要让未表达的情绪在你内心积压。如果你有强烈的感受，把它们理清并表达出来，不要让它们在内心积压到无法控制的地步！"
      },
      {
        "kind": "number",
        "text": "4. 倾听一切。尽量不要立刻摒弃任何事物。让一切浸透一会儿，然后运用判断。"
      },
      {
        "kind": "number",
        "text": "5. 对批评微笑。记住，人们不会总是同意你或理解你，即使他们非常珍视你。试着把分歧和批评视为成长的机会。事实上，那正是它。"
      },
      {
        "kind": "number",
        "text": "6. 觉察他人。记住，世界上还有 15 种以与你不同的方式看待事物的人格类型。试着识别其他人的类型。试着理解他们的视角。"
      },
      {
        "kind": "number",
        "text": "7. 对自己负责。记住，你对生活的控制超过其他任何人。"
      },
      {
        "kind": "number",
        "text": "8. 温柔地对待你的期望。如果你对他人期望太多，你总会对他们失望。对另一个人失望是赶走他们的最好方式。以你希望被对待的那种温柔对待他人。"
      },
      {
        "kind": "number",
        "text": "9. 假定最好的可能。不要因假定最坏而让自己痛苦。记住，积极的态度常常创造积极的境况。"
      },
      {
        "kind": "number",
        "text": "10. 心存疑虑时，提出问题！不要以为缺少反馈就等于负面反馈。如果你需要反馈而没有任何反馈，就去要。"
      }
