      {
        "kind": "bullet",
        "text": "• 可能评判他人而非自己"
      },
      {
        "kind": "bullet",
        "text": "• 可能以找茬为首要目的看待外部想法与人"
      },
      {
        "kind": "bullet",
        "text": "• 可能成为其常规和“照章办事”做事方式的奴隶，到任何偏离都完全不可接受的程度"
      },
      {
        "kind": "bullet",
        "text": "• 可能难以向任何人传达自己的思想与感受"
      },
      {
        "kind": "heading",
        "text": "问题解析（Explanation of Problems）"
      },
      {
        "kind": "paragraph",
        "text": "上述几乎所有问题特质都可不同程度地归因于 ISTJ 常见的问题：内倾感觉接管 ISTJ 人格，以至于所有其他功能都成为内倾感觉的奴隶。一个更“完整”的人格需要在主导功能与辅助功能之间保持良好平衡。对 ISTJ 而言，主导的内倾感觉需要得到辅助的外倾思维功能的有力支持。如果外倾思维仅仅为了支持内倾感觉的欲望而存在，那么两个功能都未被发挥出其潜力。"
      },
      {
        "kind": "paragraph",
        "text": "内倾感觉是一种不断收集数据并将其储存在某种信息数据库中以供将来随时调用的人格功能。作为人格中的主导者，它的效果是不断用需要储存的事实轰击心灵。当新事物被感知时，它被添加到内倾感觉数据的巨大仓库中。内倾感觉本身并不分析这些数据的意义或联系——它只是把数据作为信息接收。为了整理并利用这些信息，必须应用一个判断功能。正是判断功能对数据进行分析与排序。"
      },
      {
        "kind": "paragraph",
        "text": "当内倾感觉过于主导，或外倾思维发展不充分时，我们看到 ISTJ 用外倾思维安排个体的世界，使内倾感觉能够不受干扰地统治。这可能包括摒弃关系的重要性，或推开任何威胁 ISTJ 高度内倾生活方式的事物。如此，外倾思维被用来对抗外部世界，而不是对抗 ISTJ 的内在数据。它是一面防御盾牌，而非有用的过滤器。"
      },
      {
        "kind": "paragraph",
        "text": "对 ISTJ 而言，外倾思维更好、更“完整”的用途是用它来排序和评估自己丰富的内在数据储存，从而产生问题的有用解决方案与高效的体系。像所有类型一样，大多数 ISTJ 都会表现出某种这类弱点的迹象。这并不意味着他们有不可救药的缺陷。真正的问题出现在：ISTJ 人格已变得如此失衡，以至于其主人极其自私，无法考虑任何其他人视角的重要性或有效性。"
      },
      {
        "kind": "heading",
        "text": "解决方案（Solutions）"
      },
      {
        "kind": "paragraph",
        "text": "要作为个体成长，ISTJ 需要专注于：对自己的判断应用于自己收集的信息，而不是应用于来自他人的孤立事实或想法。在判断之前，把所有新数据放入现有事实的背景下。利用手头所有事实工作，将大大提高你有效判断的能力，并减少你变得冒犯性地反应和孤立的可能性。"
      },
      {
        "kind": "paragraph",
        "text": "关心个人成长的 ISTJ，会密切关注自己判断的对象，以及作出判断的动机。他们是在判断某种自身之外的东西，还是在判断自己储存知识背景内的东西？判断某事物的动机是为了理解它在世界中的用处，还是为了摒弃它？ISTJ 常常在未恰当理解某事物、且怀着摒弃它的意图时就判断它。先寻求理解，然后判断。"
      },
      {
        "kind": "heading",
        "text": "在世界中幸福生活（Living Happily）"
      },
      {
        "kind": "paragraph",
        "text": "所有人格类型的人有时都会在处理文明与人类互动的特定方面时遇到问题。对 ISTJ 而言，问题通常与以下因素有关：无法容忍超出所感知规范的行为，以及不投入努力满足他人的情感需要。这些问题源于抬高 ISTJ 内在世界的重要性、贬低外部世界的重要性。认识到自己的知识与经验可以通过他人知识与经验的协同而得到丰富的 ISTJ，会发现他们既能忠于自己的内在世界，又能与他人拥有令人满意的关系。实现这一点的关键是发展其最高的外倾功能——外倾思维（Extraverted Thinking）。"
      },
      {
        "kind": "paragraph",
        "text": "用外倾思维在外部而非内部找茬的 ISTJ，可能变得如此固执己见，以至于对他人形成僵化而不合理的期望。他们对他人理性与能力的过度警惕的判断，可能是让自己与他人保持情感距离的非常有效的方式。这将保护 ISTJ 内在世界与生活方式的神圣性，但会减少大量宝贵的输入，阻碍其社会性格的发展，并使其丰富经验数据储存的发展停滞。在极端情况下，ISTJ 可能发现自己相当孤单、孤独。"
      },
      {
        "kind": "paragraph",
        "text": "更常见的是，ISTJ 在试图排序和结构化外部世界、而非自己的内在世界时会遇到麻烦。试图把人结构进一个预先界定的、可接受的体系是有问题的。珍视独特个体的那些人格类型，会被这种对其个人明显缺乏尊重的做法冒犯；而遵循社会价值观的人格类型者，会想尊崇自己的体系，而不是被强迫遵循你的体系。许多人把被控制或被操纵体验为一种压制并加以抵抗。最终，他们可能对压制者怀有严重的怨恨。具体建议："
      },
      {
        "kind": "heading",
        "text": "具体建议（Specific Suggestions）："
      },
      {
        "kind": "paragraph",
        "text": "在对其判断之前，注意完整地倾听某人的想法。必要时提出问题。尽一切努力确保你理解那个想法。在理解细节之前，尽量不要开始判断任何事物。"
      },
      {
        "kind": "paragraph",
        "text": "试着为你生活中经常遇到的每个人判断其人格类型。记住，直觉型（Intuitive）的人常常表达方式迂回。试着对这种表达表现出宽容。"
      },
      {
        "kind": "paragraph",
        "text": "在开始与另一个人交谈之前，暂停片刻，看看那个人。感受那个人此刻的态度与感受。觉察你正在与之交谈的人。"
      },
      {
        "kind": "heading",
        "text": "十条生活准则（Ten Rules to Live By）"
      },
      {
        "kind": "number",
        "text": "1. 滋养你的优势！做那些让你出色的组织与逻辑能力得以蓬勃发展的事情。探索商业管理、会计和医学的世界。"
      },
      {
        "kind": "number",
        "text": "2. 直面你的弱点！看清你的弱点的本来面目，并寻求克服它们。尤其要努力用你的判断来审视自己内在的知识储存，而不是把它当作漠视他人想法的手段。"
      },
      {
        "kind": "number",
        "text": "3. 把想法说出来。你需要逐步梳理你大量的信息，才能把事情置于透视中。给自己适当的时间这样做，并利用与他人讨论想法的机会。一些人发现把你的想法外化是宝贵的练习，就像用写作清晰表达你的想法一样。"
      },
      {
        "kind": "number",
        "text": "4. 吸收一切。不要因为你尊重不起来产生想法的人、或因为你认为自己已经全知道，就过早摒弃想法。毕竟，每个人都有可贡献之处，没有人什么都知道。正如史蒂芬·柯维所说：“先寻求理解，然后寻求被理解。”"
      },
      {
        "kind": "number",
        "text": "5. 浇灭你控制他人的欲望。记住，大多数人不希望被控制。同样，把你的控制倾向转向内而非外。你只能真正控制自己。"
      },
      {
        "kind": "number",
        "text": "6. 觉察他人。花时间注意他人“从何而来”。他们的人格类型是什么？他们此刻感觉如何？"
      },
      {
        "kind": "number",
        "text": "7. 对自己负责。不要把生活中的问题归咎于他人。向内寻找解决方案。"
      },
      {
        "kind": "number",
        "text": "8. 温柔地对待你的期望，至少像评判他人一样严厉地评判自己。"
      },
      {
        "kind": "number",
        "text": "9. 假定最好的可能。不要沉湎于一切的黑暗面而使自己和他人痛苦。正如每一个负电荷都有一个正电荷，每一个黑暗面都有一个光明面。记住，积极的情境由积极的态度创造，反之亦然。期待最好的，最好的就会向前走来。"
      },
      {
        "kind": "number",
        "text": "10. 除了恐惧本身，没有什么可恐惧的。有时有必要冒险以开启改变。当那个时刻到来时，不要害怕冒险。在大多数情况下，挡在你目标之路上的障碍与负担并不真的存在——它们只是存在于你的视角中。改变你的视角——改变你的生活。"
      }
